import json, glob, os, collections, re, sys
B = os.path.dirname(os.path.abspath(__file__))
t = json.load(open(f'{B}/taxonomy.json'))
pages = {p['slug']: (s['id'], p) for s in t['sections'] for p in s['pages']}
raw = {}
for x in sorted(glob.glob(f'{B}/raw/*.json')):
    for r in json.load(open(x)):
        raw[r['id']] = r
feats = []
rej = collections.defaultdict(list)
for x in sorted(glob.glob(f'{B}/features/*.json')):
    sec = os.path.basename(x)[:-5]
    d = json.load(open(x))
    for f in d['features']:
        f['_sec'] = sec
        feats.append(f)
    for r in d['rejected']:
        rej[r['raw_id']].append((sec, r.get('reason')))
claimed = collections.defaultdict(list)
for f in feats:
    for i in f['raw_ids']:
        claimed[i].append(f['id'])
print('== rejected only')
for i in raw:
    if i not in claimed:
        print(i, rej[i], json.dumps(raw[i])[:700])
print('== export-colour-labels dup')
for f in feats:
    if f['id'] == 'export-colour-labels':
        print(json.dumps(f)[:700])
print('== multi-claim stats', collections.Counter(len(v) for v in claimed.values()))
def norm(s):
    return re.sub(r'[^a-z0-9]+', ' ', s.lower()).strip()
g = collections.defaultdict(list)
for f in feats:
    g[norm(f['name'])].append(f)
d = {k: v for k, v in g.items() if len(v) > 1}
print('== name dups', len(d), 'involving', sum(len(v) for v in d.values()))
samepage = sum(1 for v in d.values() if len({x['page'] for x in v}) < len(v))
print('groups with same page twice', samepage)
for k, v in list(d.items())[:50]:
    print(k, [(x['id'], x['page']) for x in v])
g = collections.defaultdict(list)
for f in feats:
    for u in f['ui']:
        g[norm(u)].append(f)
d = {k: v for k, v in g.items() if len({x['id'] for x in v}) > 1}
print('== ui dups', len(d), 'involving', len({x['id'] for v in d.values() for x in v}))
top = sorted(d.items(), key=lambda kv: -len(kv[1]))
for k, v in top[:40]:
    print(len(v), k[:80], len({x['page'] for x in v}))
g = collections.defaultdict(list)
for f in feats:
    if f['mcp']:
        g[f['mcp'][0]].append(f)
d = {k: v for k, v in g.items() if len(v) > 1}
print('== mcp primary dups', len(d), 'involving', sum(len(v) for v in d.values()), 'distinct primaries', len(g))
for k, v in sorted(d.items(), key=lambda kv: -len(kv[1]))[:30]:
    print(len(v), k, len({x['page'] for x in v}))
print('== sample of mcp field shapes', [f['mcp'] for f in feats if f['mcp']][:10])
print(collections.Counter(p for f in feats for p in [f['page'].split('/')[0]]))
print('== mcp section pages')
for s in t['sections']:
    if s['id'] in ('mcp', 'reference'):
        for p in s['pages']:
            print(p['slug'], p['kind'], p['scope'][:300])

