import json, glob, os, collections, re, sys
B = os.path.dirname(os.path.abspath(__file__))
raw = {}
for x in sorted(glob.glob(f'{B}/raw/*.json')):
    for r in json.load(open(x)):
        raw[r['id']] = r
feats = []
rej = collections.defaultdict(list)
for x in sorted(glob.glob(f'{B}/features/*.json')):
    sec = os.path.basename(x)[:-5]
    d = json.load(open(x))
    for f in d['features']:
        f['_sec'] = sec
        feats.append(f)
    for r in d['rejected']:
        rej[r['raw_id']].append((sec, r.get('reason')))
claimed = collections.defaultdict(list)
for f in feats:
    for i in f['raw_ids']:
        claimed[i].append(f['id'])
# reason shape
c = collections.Counter()
other = []
for i, l in rej.items():
    for s, r in l:
        if re.match(r'belongs to [a-z-]+$', r or ''):
            c['belongs'] += 1
        elif r and r.startswith('belongs to'):
            c['belongs+'] += 1
            other.append((i, s, r))
        else:
            c['other'] += 1
            other.append((i, s, r))
print(c)
kw = collections.Counter()
for i, s, r in other:
    kw[' '.join((r or '').split()[:3])] += 1
for k, v in kw.most_common(70):
    print(v, k)
print('=== non-belongs rejections where another section claimed it')
n = 0
cat = collections.Counter()
rows = []
for i, s, r in other:
    if i in claimed:
        n += 1
        rows.append((i, s, r, claimed[i]))
print(n)
json.dump(rows, open(f'{B}/work_conflicts.json', 'w'), indent=0)
pat = re.compile(r'not built|not shipped|does not exist|no such|removed|deferred|never|dev[- ]only|dev tool|internal|RCDev|debug|proof', re.I)
hit = [x for x in rows if pat.search(x[2] or '')]
print('notable', len(hit))
for x in hit[:150]:
    print(x[0], '|', x[1], '|', (x[2] or '')[:130], '|', x[3][:3], '|', raw[x[0]]['name'][:50])

