pages = {p['slug']: (s['id'], p) for s in t['sections'] for p in s['pages']}
raw = {}
for x in sorted(glob.glob(f'{B}/raw/*.json')):
    for r in json.load(open(x)):
        raw[r['id']] = r
feats = []
for x in sorted(glob.glob(f'{B}/features/*.json')):
    sec = os.path.basename(x)[:-5]
    for f in json.load(open(x))['features']:
        f['_sec'] = sec
        feats.append(f)
def norm(s):
    s = re.sub(r'[^a-z0-9]+', ' ', s.lower()).strip()
    s = re.sub(r'^(the|a|an) ', '', s)
    return s
STOP = set('the a an of to and or in on at is it its for with as by that this be are from your you can when not no one each so if which into than then only'.split())
def toks(s):
    return {w for w in re.findall(r'[a-z0-9_]+', s.lower()) if w not in STOP}
print('zero raw features')
for f in feats:
    if not f['raw_ids']:
        print(' ', f['id'], f['page'], f['name'], '|', f['summary'][:90], '|', f['guide_ref'], f['code_refs'][:2])
# hidden orphans
nonref = [f for f in feats if pages[f['page']][1]['kind'] != 'reference']
nametext = {norm(f['name']) for f in nonref}
uitext = {norm(u) for f in nonref for u in f['ui']}
alltext = ' '.join(norm(f['name'] + ' ' + f['summary'] + ' ' + ' '.join(f['details'])) for f in nonref)
claimed = collections.defaultdict(list)
for f in feats:
    for r in f['raw_ids']:
        claimed[r].append(f)
hid = []
for r, l in claimed.items():
    if all(pages[f['page']][1]['kind'] == 'reference' for f in l):
        rec = raw[r]
        if norm(rec['name']) in nametext or any(norm(u) in uitext for u in rec['ui']):
            continue
        hid.append(r)
