share = collections.defaultdict(int)
for r, l in claimed.items():
    for a, b in itertools.combinations(sorted({key(f) for f in l}), 2):
        share[(a, b)] += 1
cands = {}
fl = [f for f in feats if f['_sec'] not in ('mcp', 'reference')]
print('non-mirror feats', len(fl))
tk = {key(f): toks(f['summary']) for f in fl}
ui = {key(f): {norm(u) for u in f['ui']} for f in fl}
nm = {key(f): norm(f['name']) for f in fl}
GENERIC_UI = {'timeline', 'automatic', 'preview', 'preview canvas', 'edit undo'}
for a, b in itertools.combinations(fl, 2):
    ka, kb = key(a), key(b)
    k = tuple(sorted((ka, kb)))
    n = share.get(k, 0)
    same = nm[ka] == nm[kb]
    sim = difflib.SequenceMatcher(None, nm[ka], nm[kb]).quick_ratio()
    if sim >= .75:
        sim = difflib.SequenceMatcher(None, nm[ka], nm[kb]).ratio()
    j = len(tk[ka] & tk[kb]) / max(1, len(tk[ka] | tk[kb]))
    uis = (ui[ka] & ui[kb]) - GENERIC_UI
    score = None
    if n and (sim >= .7 or j >= .3):
        score = 'raw'
    elif same and (j >= .15 or uis):
        score = 'name'
    elif not n and j >= .45:
        score = 'sum'
    elif not n and uis and sim >= .8 and j >= .2:
        score = 'ui'
    if score:
        cands[k] = (score, n, round(sim, 2), round(j, 2))
print('cands', len(cands), collections.Counter(v[0] for v in cands.values()))
rows = []
for (ka, kb), v in sorted(cands.items(), key=lambda kv: (-kv[1][3], -kv[1][2])):
    a, b = idx[ka], idx[kb]
    rows.append(f"{v} {a['id']} [{a['page']}] <> {b['id']} [{b['page']}]\n   A {a['name']}: {a['summary'][:140]}\n   B {b['name']}: {b['summary'][:140]}")
open(f'{B}/work_cands.txt', 'w').write('\n'.join(rows))

