import json, glob, os, collections, re, sys, difflib
B = os.path.dirname(os.path.abspath(__file__))
feats = [f for x in sorted(glob.glob(f'{B}/features/*.json')) for f in json.load(open(x))['features']]
def norm(s):
    s = re.sub(r'[^a-z0-9]+', ' ', s.lower()).strip()
    return re.sub(r'^(the|a|an) ', '', s)
by = {}
for f in feats:
    by.setdefault(f['id'], f)
tools = sorted({t for f in feats for t in f['mcp']})
for T in tools:
    cid = 'mcp-tool-' + T.replace('_', '-')
    C = by.get(cid)
    if not C:
        print('NO CATALOG ROW', T)
        continue
    cr = set(C['raw_ids'])
    sc = []
    for f in feats:
        if f['page'].startswith(('mcp/', 'reference/')) or T not in f['mcp']:
            continue
        s = difflib.SequenceMatcher(None, norm(f['name']), norm(T)).ratio()
        sh = len(cr & set(f['raw_ids']))
        s += .4 * min(sh, 2) + (.3 if f['mcp'][0] == T else 0) + (.2 if len(f['mcp']) == 1 else 0)
        if any(norm(re.split('▸', u)[-1]) == norm(f['name']) for u in f['ui']):
            s += .4
        if T in f['name']:
            s -= .3
        sc.append((round(s, 2), f['id'], f['page'], f['name'], sh))
    sc.sort(reverse=True)
    print(T, '=>', sc[:2])
print(sorted(f['id'] for f in feats if f['id'].startswith('mcp-tool-') and f['id'][9:].replace('-', '_') not in tools))

