"""Independent read-back of what audit.py wrote: no shared state with it."""
import json, glob, os, collections, re
B = os.path.dirname(os.path.abspath(__file__))
fs = json.load(open(f'{B}/features.json'))
print('top keys', list(fs.keys()))
F = fs['features']
t = json.load(open(f'{B}/taxonomy.json'))
t0 = json.load(open(f'{B}/taxonomy.pre-audit.json'))
rej = json.load(open(f'{B}/rejected.json'))['rejected']
raw = {r['id'] for x in glob.glob(f'{B}/raw/*.json') for r in json.load(open(x))}
claimed = {i for f in F for i in f['raw_ids']}
rj = {r['raw_id'] for r in rej}
print('raw', len(raw), 'claimed', len(claimed), 'rejected', len(rj), 'unaccounted', len(raw - claimed - rj), 'both', len(claimed & rj), 'unknown', len(claimed - raw))
print('features', len(F), 'unique ids', len({f['id'] for f in F}), 'stray keys', {k for f in F for k in f if k.startswith('_')})
order = [p['slug'] for s in sorted(t['sections'], key=lambda s: s['order']) for p in sorted(s['pages'], key=lambda p: p['order'])]
rank = {s: i for i, s in enumerate(order)}
seq = [rank[f['page']] for f in F]
print('in taxonomy order', seq == sorted(seq))
cnt = collections.Counter(f['page'] for f in F)
print('empty pages', [s for s in order if not cnt[s]])
print('see_also bad', [f['id'] for f in F if any(s not in rank or s == f['page'] for s in f['see_also'])])
print('all have see_also key', all('see_also' in f for f in F))
diffs = []
for a, b in zip(t0['sections'], t['sections']):
    for pa, pb in zip(a['pages'], b['pages']):
        if pa != pb:
            diffs.append((pa['slug'], [k for k in pa if pa[k] != pb[k]]))
print('taxonomy diffs', diffs, 'same page count', sum(len(s['pages']) for s in t['sections']) == sum(len(s['pages']) for s in t0['sections']))
dev = re.compile(r'RCDev|\bdev[- ]tools?\b|snapshot_ui|perform_menu_item|cancel_sheet|select_inspector_tab|play_preview|graphic_memory|loudness_meter|land_recording|analysis_job|transcript_view|playback_rebuilds|assistant_send|assistant_answer', re.I)
print('dev', [f['id'] for f in F if dev.search(json.dumps(f, ensure_ascii=False))])
print('spotlight place', [f['id'] for f in F if 'code-history-636' in f['raw_ids']])
def norm(s):
    return re.sub(r'^(the|a|an) ', '', re.sub(r'[^a-z0-9]+', ' ', s.lower()).strip())
g = collections.defaultdict(list)
for f in F:
    g[(f['page'], norm(f['name']))].append(f['id'])
print('same page same name', [v for v in g.values() if len(v) > 1])
g = collections.defaultdict(list)
for f in F:
    g[norm(f['name'])].append(f)
un = 0
rows = []
for k, v in g.items():
    if len({x['page'] for x in v}) > 1:
        for i, a in enumerate(v):
            for b in v[i + 1:]:
                if a['page'] != b['page'] and b['page'] not in a['see_also'] and a['page'] not in b['see_also']:
                    un += 1
                    rows.append((k, a['id'], b['id']))
print('same-name pairs across pages not linked', un)
print(rows[:60])
for i in ('mcp-tool-enhance-voice', 'audio-enhance-voice', 'export-colour-labels', 'edit-copies-actions'):
    f = next(x for x in F if x['id'] == i)
    print(i, f['page'], f['see_also'], f.get('mirror_of'), f.get('merged_from'), len(f['details']))

